/// Warp divergence measurement (warp-future.2):
/// Compare 1 block x 32 threads (intra-warp divergence) vs
/// 32 blocks x 1 thread (no intra-warp divergence) for hostcall NOP round-trips.
fn run_warp_divergence_measurement(dev: Arc<CudaDevice>) -> Result<()> {
    println!("\n--- Warp Divergence Measurement (warp-future.2) ---");
    println!("  Comparing hostcall throughput: 1x32 (one warp) vs 32x1 (32 blocks)");
    println!("  Same total threads (32), same packet pool, same iterations.\n");

    let num_iters = 20;
    let num_packets: u16 = 32; // enough for all 32 threads

    // Warm-up run (1x1, 5 iters) to ensure PTX is loaded and JIT'd
    let _ = run_latency_bench_explicit(&dev, 1, 1, 5, 4);

    // Config A: 1 block x 32 threads → all threads in one warp
    // Expected: intra-warp divergence when threads are in different hostcall phases
    let mut a_wall_total = 0.0;
    let mut a_completed_total = 0u64;
    let mut a_retries_total = 0u64;
    let mut a_latencies_all: Vec<f64> = Vec::new();
    const RUNS: usize = 3;

    for _ in 0..RUNS {
        let (wall_ms, completed, retries, latencies) =
            run_latency_bench_explicit(&dev, 1, 32, num_iters, num_packets)?;
        a_wall_total += wall_ms;
        a_completed_total += completed;
        a_retries_total += retries;
        a_latencies_all.extend_from_slice(&latencies);
    }

    // Config B: 32 blocks x 1 thread → no intra-warp divergence
    // Expected: each thread is alone in its warp, no divergence
    let mut b_wall_total = 0.0;
    let mut b_completed_total = 0u64;
    let mut b_retries_total = 0u64;
    let mut b_latencies_all: Vec<f64> = Vec::new();

    for _ in 0..RUNS {
        let (wall_ms, completed, retries, latencies) =
            run_latency_bench_explicit(&dev, 32, 1, num_iters, num_packets)?;
        b_wall_total += wall_ms;
        b_completed_total += completed;
        b_retries_total += retries;
        b_latencies_all.extend_from_slice(&latencies);
    }

    // Compute statistics
    a_latencies_all.sort_by(|a, b| a.partial_cmp(b).unwrap());
    b_latencies_all.sort_by(|a, b| a.partial_cmp(b).unwrap());

    let a_mean = if a_latencies_all.is_empty() {
        0.0
    } else {
        a_latencies_all.iter().sum::<f64>() / a_latencies_all.len() as f64
    };
    let b_mean = if b_latencies_all.is_empty() {
        0.0
    } else {
        b_latencies_all.iter().sum::<f64>() / b_latencies_all.len() as f64
    };

    let a_p50 = percentile(&a_latencies_all, 50.0);
    let b_p50 = percentile(&b_latencies_all, 50.0);

    let a_throughput = if a_wall_total > 0.0 {
        a_completed_total as f64 / (a_wall_total / 1000.0)
    } else {
        0.0
    };
    let b_throughput = if b_wall_total > 0.0 {
        b_completed_total as f64 / (b_wall_total / 1000.0)
    } else {
        0.0
    };

    let a_cas = if a_completed_total > 0 {
        a_retries_total as f64 / a_completed_total as f64
    } else {
        0.0
    };
    let b_cas = if b_completed_total > 0 {
        b_retries_total as f64 / b_completed_total as f64
    } else {
        0.0
    };

    println!("  Config A (1 block x 32 threads — one warp, intra-warp divergence):");
    println!(
        "    wall={:.1}ms  completed={}/{}  mean={:.0}ns  p50={:.0}ns  CAS/call={:.2}  throughput={:.0}/s",
        a_wall_total / RUNS as f64,
        a_completed_total / RUNS as u64,
        32 * num_iters,
        a_mean,
        a_p50,
        a_cas,
        a_throughput / RUNS as f64,
    );

    println!("\n  Config B (32 blocks x 1 thread — no intra-warp divergence):");
    println!(
        "    wall={:.1}ms  completed={}/{}  mean={:.0}ns  p50={:.0}ns  CAS/call={:.2}  throughput={:.0}/s",
        b_wall_total / RUNS as f64,
        b_completed_total / RUNS as u64,
        32 * num_iters,
        b_mean,
        b_p50,
        b_cas,
        b_throughput / RUNS as f64,
    );

    println!("\n  --- Comparison ---");
    let throughput_ratio = if b_throughput > 0.0 {
        a_throughput / b_throughput
    } else {
        f64::NAN
    };
    let latency_ratio = if b_mean > 0.0 {
        a_mean / b_mean
    } else {
        f64::NAN
    };
    let cas_ratio = if b_cas > 0.0 {
        a_cas / b_cas
    } else {
        f64::NAN
    };

    println!("    Throughput ratio (A/B): {:.2}x", throughput_ratio);
    println!("    Latency ratio (A/B):   {:.2}x", latency_ratio);
    println!("    CAS retry ratio (A/B): {:.2}x", cas_ratio);

    if throughput_ratio >= 0.8 {
        println!("\n  RESULT: Intra-warp divergence has MINIMAL impact (<20% throughput loss).");
        println!("  WarpFuture optimization may not be justified for hostcall-bound workloads.");
    } else if throughput_ratio >= 0.5 {
        println!("\n  RESULT: Intra-warp divergence causes MODERATE impact ({:.0}% throughput loss).",
            (1.0 - throughput_ratio) * 100.0);
        println!("  WarpFuture could provide meaningful improvement.");
    } else {
        println!("\n  RESULT: Intra-warp divergence causes SEVERE impact ({:.0}% throughput loss).",
            (1.0 - throughput_ratio) * 100.0);
        println!("  WarpFuture is strongly justified.");
    }

    println!("\n  Measurement complete.");
    Ok(())
}

/// Test warp intrinsics: syncwarp + shfl.sync.idx on hardware.
///
/// Launches 1 block x 32 threads. Lane 0 writes 0xCAFE_BABE, broadcasts
/// via shfl.sync.idx.b32 to all lanes. Verifies all 32 outputs match.
fn run_warp_intrinsics_test(dev: Arc<CudaDevice>) -> Result<()> {
    println!("\n--- Warp Intrinsics Test (warp-future.3) ---");

    let ptx = cudarc::nvrtc::Ptx::from_src(KERNEL_PTX);
    let _ = dev.load_ptx(ptx, "kernel", &["test_warp_intrinsics"]);
    let f = dev
        .get_func("kernel", "test_warp_intrinsics")
        .ok_or(GpuHostError::KernelNotFound("test_warp_intrinsics"))?;

    // Allocate mapped output for 32 u32 values
    let (output_host, output_dev) = unsafe { alloc_mapped_result_array(&dev, 32)? };

    let cfg = LaunchConfig {
        grid_dim: (1, 1, 1),
        block_dim: (32, 1, 1),
        shared_mem_bytes: 0,
    };

    unsafe {
        f.launch(cfg, (output_dev as u64,))?;
    }
    dev.synchronize()?;

    // Verify all 32 lanes received 0xCAFE_BABE
    let expected = 0xCAFE_BABEu32;
    let mut pass_count = 0u32;
    for lane in 0..32 {
        let val = unsafe { std::ptr::read_volatile(output_host.add(lane)) };
        if val == expected {
            pass_count += 1;
        } else {
            println!("  FAIL: lane {} got 0x{:08X}, expected 0x{:08X}", lane, val, expected);
        }
    }

    if pass_count == 32 {
        println!("  PASSED: all 32 lanes received 0xCAFE_BABE via shfl.sync.idx.b32");
        println!("  bar.warp.sync + shfl.sync.idx.b32 confirmed working on hardware.");
    } else {
        println!("  FAILED: only {}/32 lanes received correct value", pass_count);
    }

    unsafe { free_mapped_mem(output_host)? };
    Ok(())
}

/// WarpFuture PoC test: 32 lanes cooperatively send a PRINT hostcall.
///
/// Launches 1 block x 32 threads. All lanes execute the WarpPrintFuture
/// state machine via WarpExecutor. The message "WarpFuture: ABCDEFGHIJKLMNOP..."
/// should appear on the host.
fn run_warp_future_print_test(dev: Arc<CudaDevice>) -> Result<()> {
    println!("\n--- WarpFuture PoC Test (warp-future.4) ---");

    let hc_buf = hostcall::HostcallBuffer::new(4)?;
    let dev_ptr = hc_buf.dev_ptr;

    let (result_host, result_dev) = unsafe { alloc_mapped_result_array(&dev, 1)? };

    let hc_buf_ref = std::sync::Arc::new(hc_buf);
    let hc_buf_listener = std::sync::Arc::clone(&hc_buf_ref);

    let msg_received = std::sync::Arc::new(std::sync::Mutex::new(String::new()));
    let msg_clone = std::sync::Arc::clone(&msg_received);

    let listener_handle = std::thread::spawn(move || {
        hc_buf_listener.listen(move |msg| {
            let text = String::from_utf8_lossy(msg);
            let mut guard = msg_clone.lock().unwrap();
            *guard = text.to_string();
            println!("  [HOST] WarpFuture says: \"{}\"", text);
        });
    });

    let ptx = cudarc::nvrtc::Ptx::from_src(KERNEL_PTX);
    let _ = dev.load_ptx(ptx, "kernel", &["warp_future_print_test"]);
    let f = dev
        .get_func("kernel", "warp_future_print_test")
        .ok_or(GpuHostError::KernelNotFound("warp_future_print_test"))?;

    // Launch: 1 block x 32 threads (1 full warp)
    let cfg = LaunchConfig {
        grid_dim: (1, 1, 1),
        block_dim: (32, 1, 1),
        shared_mem_bytes: 0,
    };

    let start = std::time::Instant::now();
    unsafe {
        f.launch(cfg, (dev_ptr as u64, result_dev as u64))?;
    }
    dev.synchronize()?;
    let elapsed = start.elapsed();

    std::thread::sleep(std::time::Duration::from_millis(100));
    hc_buf_ref.signal_shutdown();
    listener_handle.join().unwrap();

    let result_val = unsafe { std::ptr::read_volatile(result_host) };

    println!("  Result: {} (1=success)", result_val);
    println!("  Elapsed: {:.3}ms", elapsed.as_secs_f64() * 1000.0);

    let received_msg = msg_received.lock().unwrap();
    if result_val == 1 && received_msg.starts_with("WarpFuture: ") {
        println!("  WarpFuture PoC: PASSED!");
        println!("    32 lanes cooperatively built and sent a message via WarpFuture trait.");
        println!("    State machine: INIT -> WAIT -> DONE (zero divergence by construction).");
    } else if result_val == 1 {
        println!("  WarpFuture completed but message format unexpected: \"{}\"", *received_msg);
    } else {
        println!("  WarpFuture PoC: FAILED (result={})", result_val);
    }

    unsafe { free_mapped_mem(result_host)? };
    Ok(())
}

/// WarpFuture multi-hostcall test: 3 sequential PRINT calls in one WarpFuture (warp-future.6).
///
/// Validates that a WarpFuture state machine can compose multiple sequential
/// hostcalls while maintaining warp convergence. Expects 3 messages received in order.
fn run_warp_future_multi_print_test(dev: Arc<CudaDevice>) -> Result<()> {
    println!("\n--- WarpFuture Multi-Hostcall Test (warp-future.6) ---");

    let hc_buf = hostcall::HostcallBuffer::new(4)?;
    let dev_ptr = hc_buf.dev_ptr;

    let (result_host, result_dev) = unsafe { alloc_mapped_result_array(&dev, 1)? };

    let hc_buf_ref = std::sync::Arc::new(hc_buf);
    let hc_buf_listener = std::sync::Arc::clone(&hc_buf_ref);

    let messages = std::sync::Arc::new(std::sync::Mutex::new(Vec::<String>::new()));
    let msg_clone = std::sync::Arc::clone(&messages);

    let listener_handle = std::thread::spawn(move || {
        hc_buf_listener.listen(move |msg| {
            let text = String::from_utf8_lossy(msg).to_string();
            println!("  [HOST] WarpMulti says: \"{}\"", text);
            let mut guard = msg_clone.lock().unwrap();
            guard.push(text);
        });
    });

    let ptx = cudarc::nvrtc::Ptx::from_src(KERNEL_PTX);
    let _ = dev.load_ptx(ptx, "kernel", &["warp_future_multi_print_test"]);
    let f = dev
        .get_func("kernel", "warp_future_multi_print_test")
        .ok_or(GpuHostError::KernelNotFound("warp_future_multi_print_test"))?;

    let cfg = LaunchConfig {
        grid_dim: (1, 1, 1),
        block_dim: (32, 1, 1),
        shared_mem_bytes: 0,
    };

    let start = std::time::Instant::now();
    unsafe {
        f.launch(cfg, (dev_ptr as u64, result_dev as u64))?;
    }
    dev.synchronize()?;
    let elapsed = start.elapsed();

    std::thread::sleep(std::time::Duration::from_millis(100));
    hc_buf_ref.signal_shutdown();
    listener_handle.join().unwrap();

    let result_val = unsafe { std::ptr::read_volatile(result_host) };
    let msgs = messages.lock().unwrap();

    println!("  Result: {} (1=success)", result_val);
    println!("  Elapsed: {:.3}ms", elapsed.as_secs_f64() * 1000.0);
    println!("  Messages received: {}", msgs.len());

    if result_val == 1 && msgs.len() == 3 {
        let ok1 = msgs[0].contains("1/3");
        let ok2 = msgs[1].contains("2/3");
        let ok3 = msgs[2].contains("3/3");
        if ok1 && ok2 && ok3 {
            println!("  WarpFuture Multi-Hostcall: PASSED!");
            println!("    3 sequential hostcalls completed in order.");
            println!("    7-state machine: INIT1→WAIT1→INIT2→WAIT2→INIT3→WAIT3→DONE");
            println!("    Composition of WarpFuture hostcalls verified on hardware.");
        } else {
            println!("  Messages out of order or unexpected content:");
            for (i, m) in msgs.iter().enumerate() {
                println!("    [{}]: \"{}\"", i, m);
            }
        }
    } else {
        println!("  WarpFuture Multi-Hostcall: FAILED (result={}, msgs={})", result_val, msgs.len());
        for (i, m) in msgs.iter().enumerate() {
            println!("    [{}]: \"{}\"", i, m);
        }
    }

    unsafe { free_mapped_mem(result_host)? };
    Ok(())
}

/// GPU panic handler test: verify panic message is received via hostcall.
///
/// The test kernel deliberately panics. We expect:
/// 1. The panic message appears on stderr via [GPU PANIC] prefix
/// 2. The kernel returns a CUDA error (due to trap instruction)
/// 3. The result marker is set to 1 (written before the panic)
fn run_panic_test(dev: Arc<CudaDevice>) -> Result<()> {
    println!("\n--- GPU Panic Handler Test (gpu-panic.2) ---");

    let hc_buf = hostcall::HostcallBuffer::new(4)?;
    let dev_ptr = hc_buf.dev_ptr;

    let (result_host_ptr, result_dev_ptr) = unsafe { alloc_mapped_result_array(&dev, 1)? };

    let hc_buf_ref = std::sync::Arc::new(hc_buf);
    let hc_buf_listener = std::sync::Arc::clone(&hc_buf_ref);
    let listener_handle = std::thread::spawn(move || {
        hc_buf_listener.listen(|msg| {
            let s = std::str::from_utf8(msg).unwrap_or("<invalid>");
            println!("  [GPU PRINT] {}", s);
        });
    });

    let ptx = cudarc::nvrtc::Ptx::from_src(KERNEL_PTX);
    let _ = dev.load_ptx(ptx, "panic_test", &["panic_test_kernel"]);
    let f = dev.get_func("panic_test", "panic_test_kernel")
        .ok_or(GpuHostError::KernelNotFound("panic_test_kernel"))?;

    let cfg = LaunchConfig {
        grid_dim: (1, 1, 1),
        block_dim: (1, 1, 1),
        shared_mem_bytes: 0,
    };

    println!("  Launching panic_test_kernel (expects GPU panic + trap)...");
    unsafe {
        f.launch(cfg, (dev_ptr as u64, result_dev_ptr as u64))?;
    }

    // Use raw CUDA API for synchronization since cudarc's synchronize may
    // unwrap internally. trap instruction will cause CUDA_ERROR_LAUNCH_FAILED.
    let sync_result = unsafe {
        let cu = cuda_lib();
        cu.cuCtxSynchronize()
    };

    // Give listener time to process the panic packet
    std::thread::sleep(std::time::Duration::from_millis(200));
    hc_buf_ref.signal_shutdown();
    listener_handle.join().unwrap();

    let marker = unsafe { std::ptr::read_volatile(result_host_ptr) };

    println!("  Result marker: {} (expected 1 = reached panic point)", marker);
    println!("  CUDA sync result: {:?} (LAUNCH_FAILED expected from trap)", sync_result);

    // The test passes if:
    // 1. The marker was set to 1 (code reached the panic point)
    // 2. The [GPU PANIC] message appeared on stderr (visible in console output)
    if marker == 1 {
        println!("  panic_test: PASSED (panic message sent via hostcall before trap)");
    } else {
        println!("  panic_test: marker was {} (expected 1)", marker);
    }

    // IMPORTANT: trap instruction puts the CUDA context in an error state.
    // CudaDevice's Drop impl will try to sync and panic on the sticky error.
    // Exit the process cleanly before Drop runs.
    println!("  Note: Exiting to avoid CudaDevice Drop panic after trap.");
    std::process::exit(0);
}

